export function createCourseMap(host,{L,onStatus=()=>{},geolocation=globalThis.navigator?.geolocation,now=()=>Date.now()}={}){
 const map=L.map(host,{scrollWheelZoom:true}).setView([43.187,-124.391],15);
 map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');
 L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>onStatus('Map tiles unavailable. Hole photos and flyovers remain available.')).addTo(map);
 let courseId=null,course,watch=null,marker=null,circle=null,updated=0,accuracy=null,disposed=false;
 function status(){if(!updated)return 'GPS is off. No shared group feed is connected.';const age=Math.max(0,Math.floor((now()-updated)/1000));return `Your device · ±${Math.round(accuracy)}m · ${age}s old${age>90?' · STALE':''}. Coordinates stay in this browser.`;}
 return {map,setCourse(c){course=c;if(c.id!==courseId){courseId=c.id;map.setView(c.center,15);}},resize(){map.invalidateSize();},overview(){if(course)map.setView(course.center,15);},status,
 startGPS(){if(disposed||watch!==null)return;if(!geolocation){onStatus('Location is unavailable in this browser.');return;}onStatus('Waiting for your location permission…');let first=true;watch=geolocation.watchPosition(p=>{if(disposed)return;updated=p.timestamp;accuracy=p.coords.accuracy;const point=[p.coords.latitude,p.coords.longitude];if(!marker){circle=L.circle(point,{radius:accuracy,color:'#5e9fea',fillOpacity:.1,weight:1}).addTo(map);marker=L.circleMarker(point,{radius:9,color:'#fff',weight:3,fillColor:'#4389dd',fillOpacity:1}).bindTooltip('Your device · real GPS',{permanent:true}).addTo(map);}else{circle.setLatLng(point).setRadius(accuracy);marker.setLatLng(point);}if(first){map.setView(point,17);first=false;}onStatus(status());},e=>onStatus(e.code===1?'Location permission declined. You can still browse the course.':`GPS unavailable: ${e.message}`),{enableHighAccuracy:true,maximumAge:15000,timeout:30000});},
 stopGPS(){if(watch!==null)geolocation.clearWatch(watch);watch=null;marker?.remove();circle?.remove();marker=null;circle=null;updated=0;onStatus('GPS stopped. No locations were uploaded.');},dispose(){this.stopGPS();disposed=true;map.remove();}};
}
